# Surah Al-A'raf (chapter 7) — part 3: ayat 21-30 (IDs 975-984)
SURAH = 7

ENTRIES = {
975: (
"اور ان دونوں کو قسم دلائی — یقیناً میں تمہارا خیر خواہ ہوں",
"""۱۔ شیطان اپنی خیر خواہی کی قسم کھا کر دھوکہ دیتا ہے۔
۲۔ ’’وَقَاسَمَهُمَا إِنِّي لَكُمَا لَمِنَ النَّاصِحِينَ‘‘ — اور ان دونوں کو قسم دلائی — یقیناً میں تمہارا خیر خواہ ہوں — یعنی شیطان نے پختہ قسم کھا کر انہیں باور کرایا کہ وہ ان کا خیر خواہ ہے۔
۳۔ عملی سبق: دھوکہ باز بھی قسم کھا سکتا ہے؛ قول کی بجائے حکمت اور قرآن سے تمییز کرو۔"""
),
976: (
"پس — شیطان نے ان دونوں کو دھوکے سے نیچے گرایا — پھر جب ان دونوں نے اس درخت کا ذائقہ چکھا — ان کی شرمگاہیں ان کے لیے ظاہر ہو گئیں — اور وہ جنت کے پتوں سے اپنے آپ کو ڈھانپنے لگے — اور ان کے رب نے ان دونوں کو پکارا: کیا میں نے تم دونوں کو اس درخت سے منع نہیں کیا تھا — اور کیا میں نے تم سے یہ نہیں کہا تھا کہ شیطان تمہارا کھلا دشمن ہے",
"""۱۔ آدم و حواؑ کی آدمؑ کی خطا اور اللہ کی پکار۔
۲۔ ’’فَدَلَّاهُمَا بِغُرُورٍ فَلَمَّا ذَاقَا الشَّجَرَۃَ بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّۃِ وَنَادَاهُمَا رَبُّهُمَا أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا الشَّجَرَۃِ وَأَقُل لَّكُمَا إِنَّ الشَّيْطَانَ لَكُمَا عَدُوٌّ مُّبِينٌ‘‘ — پس — شیطان نے ان دونوں کو دھوکے سے نیچے گرایا — پھر جب ان دونوں نے اس درخت کا ذائقہ چکھا — ان کی شرمگاہیں ان کے لیے ظاہر ہو گئیں — اور وہ جنت کے پتوں سے اپنے آپ کو ڈھانپنے لگے — اور ان کے رب نے ان دونوں کو پکارا — کیا میں نے تم دونوں کو اس درخت سے منع نہیں کیا تھا — اور کیا میں نے تم سے یہ نہیں کہا تھا کہ شیطان تمہارا کھلا دشمن ہے — یعنی منع کیا ہوا کام کر لینے کے بعد فوراً پشیمانی اور اللہ کی پکار ہوئی۔
۳۔ عملی سبق: اللہ کی منع کردہ چیز سے دور رہو؛ گناہ کے بعد توبہ کرو۔"""
),
977: (
"ان دونوں نے کہا: اے ہمارے رب — ہم نے اپنی جانوں پر ظلم کیا — اور اگر تو نے ہمیں بخش نہ دیا اور ہم پر رحم نہ کیا — تو ہم ضرور خسارہ پانے والوں میں سے ہو جائیں گے",
"""۱۔ آدم و حواؑ کی توبہ — عاجزی کی بہترین مثال۔
۲۔ ’’قَالَا رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ‘‘ — ان دونوں نے کہا: اے ہمارے رب — ہم نے اپنی جانوں پر ظلم کیا — اور اگر تو نے ہمیں بخش نہ دیا اور ہم پر رحم نہ کیا — تو ہم ضرور خسارہ پانے والوں میں سے ہو جائیں گے — یعنی یہ توبہ کا طریقہ ہے: اپنی خطا کا اقرار اور اللہ کی رحمت پر اعتماد۔
۳۔ شیعوں کے نزدیک آدم و حواؑ کی یہ خطا ایک اجتہادی چوک تھی — یہ — گناہِ کبیرہ نہیں — اور ان کی توبہ قبول ہو گئی۔
۴۔ عملی سبق: گناہ کے بعد جلد توبہ کرو؛ اللہ کی مغفرت ہمیشہ دسترس میں ہے۔"""
),
978: (
"اللہ نے کہا: تم — سب — نیچے اترو — تم میں سے ہر ایک دوسرے کا دشمن ہے — اور تمہارے لیے زمین میں — ایک وقت تک — ٹھکانا اور سامان ہے",
"""۱۔ دنیا — عارضی ٹھکانا — لڑنا جھگڑنا بھی طے۔
۲۔ ’’قَالَ اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتَاعٌ إِلَىٰ حِينٍ‘‘ — اللہ نے کہا: تم — سب — نیچے اترو — تم میں سے ہر ایک دوسرے کا دشمن ہے — اور تمہارے لیے زمین میں — ایک وقت تک — ٹھکانا اور سامان ہے — یعنی زمین میں ایک مقررہ مدت تک رہنا ہے — شیطان اور انسان کی دشمنی تاریخی ہے۔
۳۔ عملی سبق: دنیا میں رہتے ہوئے اللہ کو یاد رکھو؛ اس میں فرقہ وارانہ دشمنی نہیں بلکہ مقابلۂ خیر خواہی ہے۔"""
),
979: (
"اللہ نے کہا: — وہاں تم زندہ رہو گے — اور — وہاں موت پاؤ گے — اور — وہاں سے — دوبارہ اٹھائے جاؤ گے",
"""۱۔ زمین حیات کا ڈور ہے — مگر موت اور حشر سے بچ نہیں سکتے۔
۲۔ ’’قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ‘‘ — اللہ نے کہا: — وہاں تم زندہ رہو گے — اور — وہاں موت پاؤ گے — اور — وہاں سے — دوبارہ اٹھائے جاؤ گے — یعنی زمین انسان کا گھر ہے — جو اسی میں پیدا ہوا — اسی میں مرے گا اور اسی سے دوبارہ اٹھے گا۔
۳۔ عملی سبق: موت — یقینی ہے؛ یہاں کی زندگی کو آخرت کے لیے استعمال کرو۔"""
),
980: (
"اے آدم کی اولاد — ہم نے تم پر — تمہاری شرمگاہ ڈھانپنے کا لباس اتارا — اور زینت بھی — اور تقویٰ کا لباس — وہ — بہتر ہے — یہ اللہ کی آیات میں سے ہے — شاید وہ نصیحت حاصل کریں",
"""۱۔ لباس — اللہ کی نعمت — اور تکوا — اصل لباس۔
۲۔ ’’يَا بَنِي آدَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَارِي سَوْآتِكُمْ وَرِيشًا وَلِبَاسُ التَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ آيَاتِ اللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ‘‘ — اے آدم کی اولاد — ہم نے تم پر — تمہاری شرمگاہ ڈھانپنے کا لباس اتارا — اور زینت بھی — اور تقویٰ کا لباس — وہ — بہتر ہے — یہ اللہ کی آیات میں سے ہے — شاید وہ نصیحت حاصل کریں — یعنی ظاہری لباس — داخلی تقویٰ سے بہتر نہیں۔
۳۔ عملی سبق: لباس — شرم کا تحفظ ہے — اور تقویٰ روح کی زینت ہے؛ باطل میں شامل مت بنو۔"""
),
981: (
"اے آدم کی اولاد — شیطان تمہیں — ویسا ہی فتنوں میں نہ ڈالے — جیسے اس نے تمہارے ماں باپ کو جنت سے — ان کے لباس اتار کر — ان کی شرمگاہیں انہیں دکھانے کے لیے — نکالا تھا — بے شک وہ تمہیں — اپنے لشکر سمیت — ایسی جگہ سے دیکھتا ہے — جہاں سے تمہیں نہیں دکھائی دیتا — بے شک ہم نے شیاطین کو — ان لوگوں کا کارساز بنایا ہے — جو ایمان نہیں لاتے",
"""۱۔ شیطان — انسان کی شرم سے کھیلنے والا۔
۲۔ ’’يَا بَنِي آدَمَ لَا يَفْتِنَنَّكُمُ الشَّيْطَانُ كَمَا أَخْرَجَ أَبَوَيْكُم مِّنَ الْجَنَّۃِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْآتِهِمَا إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لَا تَرَوْنَهُمْ إِنَّا جَعَلْنَا الشَّيَاطِينَ أَوْلِيَاءَ لِّلَّذِينَ لَا يُؤْمِنُونَ‘‘ — اے آدم کی اولاد — شیطان تمہیں — ویسا ہی فتنوں میں نہ ڈالے — جیسے اس نے تمہارے ماں باپ کو جنت سے — ان کے لباس اتار کر — ان کی شرمگاہیں انہیں دکھانے کے لیے — نکالا تھا — بے شک وہ تمہیں — اپنے لشکر سمیت — ایسی جگہ سے دیکھتا ہے — جہاں سے تمہیں نہیں دکھائی دیتا — بے شک ہم نے شیاطین کو — ان لوگوں کا کارساز بنایا ہے — جو ایمان نہیں لاتے — یعنی شیطان — نظر نہ آنے والا دشمن ہے — لہٰذا مؤمن بچتے رہیں۔
۳۔ عملی سبق: شیطان کی طاقت — نظریں نہ آنے میں ہے — ایمان کی طاقت — اللہ پر توکل میں ہے۔"""
),
982: (
"اور — جب وہ کوئی بے حیائی کا کام کرتے ہیں — تو کہتے ہیں: ہم نے اپنے باپ دادا کو اسی پر پایا — اور اللہ نے بھی ہمیں اسی کا حکم دیا — کہدو: بے شک اللہ — بے حیائی کا حکم نہیں دیتا — کیا تم اللہ پر وہ — کہتے ہو — جو تم جانتے نہیں",
"""۱۔ اندھا تقلید — اللہ کے حکم کی بجائے آبائی رواج۔
۲۔ ’’وَإِذَا فَعَلُوا فَاحِشَۃً قَالُوا وَجَدْنَا عَلَيْهَا آبَاءَنَا وَاللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ اللَّهَ لَا يَأْمُرُ بِالْفَحْشَاءِ أَتَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ‘‘ — اور — جب وہ کوئی بے حیائی کا کام کرتے ہیں — تو کہتے ہیں: ہم نے اپنے باپ دادا کو اسی پر پایا — اور اللہ نے بھی ہمیں اسی کا حکم دیا — کہدو: بے شک اللہ — بے حیائی کا حکم نہیں دیتا — کیا تم اللہ پر وہ — کہتے ہو — جو تم جانتے نہیں — یعنی اللہ کو — غلط الزام دینے سے بڑا گناہ نہیں۔
۳۔ عملی سبق: آبائی رواج — قرآن اور سنت کے مطابق نہ ہو تو مت چلو؛ اللہ کی بجائے کسی کا نام نہ لو۔"""
),
983: (
"کہدو: میرے رب نے مجھے انصاف کا حکم دیا — اور ہر سجدہ گاہ پر — اپنے چہرے قائم کرو — اور صرف اسی کو خالص ہو کر — پکارو — جس طرح اس نے تمہیں پہلی بار پیدا کیا — اسی طرح تم واپس آؤ گے",
"""۱۔ انصاف اور اخلاص — بنیادی حکم۔
۲۔ ’’قُلْ أَمَرَ رَبِّي بِالْقِسْطِ وَأَقِيمُوا وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ كَمَا بَدَأَكُمْ تَعُودُونَ‘‘ — کہدو: میرے رب نے مجھے انصاف کا حکم دیا — اور ہر سجدہ گاہ پر — اپنے چہرے قائم کرو — اور صرف اسی کو خالص ہو کر — پکارو — جس طرح اس نے تمہیں پہلی بار پیدا کیا — اسی طرح تم واپس آؤ گے — یعنی انصاف کی دعوت اور اخلاصِ دین — آپ کی بعثت کا مرکز ہے۔
۳۔ شیعوں کے نزدیک ’’کل مسجد‘‘ سے ہر وہ جگہ مراد جہاں اللہ کی یاد ہو؛ سجدے میں پیشانی — اللہ کے سامنے عاجزی کا اظہار ہے۔
۴۔ عملی سبق: انصاف کرو اور اخلاصِ دین پر قائم رہو؛ موت کے بعد حشر — یقینی ہے۔"""
),
984: (
"ایک گروہ — اللہ نے ہدایت دی — اور ایک گروہ — ان پر گمراہی لازم ہو گئی — بے شک انہوں نے — اللہ کے علاوہ — شیطانوں کو کارساز بنا لیا — اور — وہ سمجھتے ہیں کہ — وہ راہ ہدایت پر ہیں",
"""۱۔ ہدایت اور گمراہی — دونوں — اللہ کی طرف سے ازمایا گیا انتخاب۔
۲۔ ’’فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ الضَّلَالَۃُ إِنَّهُمُ اتَّخَذُوا الشَّيَاطِينَ أَوْلِيَاءَ مِن دُونِ اللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ‘‘ — ایک گروہ — اللہ نے ہدایت دی — اور ایک گروہ — ان پر گمراہی لازم ہو گئی — بے شک انہوں نے — اللہ کے علاوہ — شیطانوں کو کارساز بنا لیا — اور — وہ سمجھتے ہیں کہ — وہ راہ ہدایت پر ہیں — یعنی خود کو راہ یافتہ سمجھنے والے بھی گمراہ ہو سکتے ہیں اگر اللہ کے علاوہ — کسی کو نصب کر لیں۔
۳۔ عملی سبق: ہدایت کا اندازہ — خود کے احساس سے نہیں ہوتا؛ قرآن و اہلِ بیتؑ کے معیار پر پرکھا جاتا ہے۔"""
),
}
